'use strict';

/**
 * Converts a raw OpenWeatherMap /weather API response into a
 * channel-agnostic customer weather update object.
 *
 * The output format (customer_weather_update_v1) carries no assumptions
 * about the delivery channel — the same object works for email, WhatsApp,
 * SMS, or any other channel without modification.
 *
 * @param {object|object[]} raw - Raw OpenWeatherMap response (object or single-item array)
 * @returns {{ format: string, type: string, location: string, headline: string, message: string, context: object }}
 * @throws {Error} If the response is missing, empty, or lacks required fields
 */
function formatWeatherUpdate(raw) {
  // Unwrap array (n8n HTTP Request nodes return arrays)
  if (Array.isArray(raw)) {
    if (raw.length === 0) throw new Error('Invalid OpenWeatherMap response');
    raw = raw[0];
  }

  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('Invalid OpenWeatherMap response');
  }
  if (!raw.main || typeof raw.main !== 'object') {
    throw new Error('Invalid OpenWeatherMap response');
  }

  // --- Extract fields, omitting any that are missing/undefined ---
  const location = (raw.name && String(raw.name).trim()) || 'Your location';
  const condition = raw.weather?.[0]?.description ?? null;

  const rawTemp    = raw.main.temp;
  const rawFeels   = raw.main.feels_like;
  const rawHumid   = raw.main.humidity;
  const rawWind    = raw.wind?.speed;
  const rawVis     = raw.visibility;
  const rawClouds  = raw.clouds?.all;

  const temp       = rawTemp    != null ? Math.round(rawTemp)              : null;
  const feelsLike  = rawFeels   != null ? Math.round(rawFeels)             : null;
  const humidity   = rawHumid   != null ? rawHumid                         : null;
  const windKmh    = rawWind    != null ? Math.round(rawWind * 3.6)        : null;
  const visKm      = rawVis     != null ? rawVis / 1000                    : null;
  const clouds     = rawClouds  != null ? rawClouds                        : null;

  // --- Build context (only include present fields) ---
  const context = {};
  if (condition !== null)  context.condition          = condition;
  if (temp      !== null)  context.temperature_c      = temp;
  if (feelsLike !== null)  context.feels_like_c       = feelsLike;
  if (humidity  !== null)  context.humidity_percent   = humidity;
  if (windKmh   !== null)  context.wind_speed_kmh     = windKmh;
  if (visKm     !== null)  context.visibility_km      = visKm;
  if (clouds    !== null)  context.cloud_cover_percent = clouds;

  const message = buildMessage({ location, condition, temp, feelsLike, humidity, windKmh, visKm });

  return {
    format:   'customer_weather_update_v1',
    type:     'daily_weather_update',
    location,
    headline: `Today's weather update for ${location}`,
    message,
    context,
  };
}

/**
 * Builds the human-readable message string from normalised weather params.
 * Always begins with "Good morning! ".
 *
 * @private
 */
function buildMessage({ location, condition, temp, feelsLike, humidity, windKmh, visKm }) {
  const desc = (condition || '').toLowerCase();

  // --- Condition detection (priority order) ---
  const isThunderstorm = desc.includes('thunderstorm');
  const isRain  = !isThunderstorm && (desc.includes('rain') || desc.includes('drizzle') || desc.includes('shower'));
  const isMist  = !isRain && (desc.includes('mist') || desc.includes('fog') || desc.includes('haze') ||
                               desc.includes('smoke') || desc.includes('dust') || desc.includes('sand'));
  const isCloudy = !isMist && (desc.includes('cloud') || desc.includes('overcast'));
  const isClear  = !isCloudy && (desc.includes('clear') || desc.includes('sunny') || desc.includes('fair'));

  const isPartly = desc.includes('few') || desc.includes('scattered') || desc.includes('broken');

  // --- Opening phrase ---
  let opening;
  if (isThunderstorm) {
    opening = `${location} is expecting stormy weather today`;
  } else if (isRain) {
    opening = `${location} looks rainy today`;
  } else if (isMist) {
    opening = `${location} is looking misty today`;
  } else if (isCloudy) {
    opening = `${location} looks ${isPartly ? 'partly cloudy' : 'cloudy'} today`;
  } else if (isClear) {
    opening = `${location} looks clear and sunny today`;
  } else {
    opening = `${location} has ${condition || 'mixed'} conditions today`;
  }

  // --- Temperature clause ---
  let tempClause = '';
  if (temp !== null) {
    tempClause = `, around ${temp}°C`;
    if (feelsLike !== null && feelsLike !== temp) {
      tempClause += ` but feeling closer to ${feelsLike}°C`;
    }
  }

  // --- Humidity clause ---
  const humidClause = (humidity !== null && humidity >= 75) ? ' with high humidity' : '';

  // --- Breeze clause ---
  const breezeClause = (windKmh !== null && windKmh > 20) ? ' and a steady breeze' : '';

  // --- Advice suffix (first matching rule wins) ---
  const isHot      = (feelsLike !== null && feelsLike >= 35) || (humidity !== null && humidity >= 75);
  const isCool     = temp !== null && temp <= 18;
  const isLowVis   = visKm !== null && visKm < 2;

  let advice = '';
  if (isThunderstorm) {
    advice = ' — stay safe and avoid open areas ⛈️';
  } else if (isRain) {
    advice = ' — carry an umbrella ☂️';
  } else if (isMist || isLowVis) {
    advice = ' — take care while travelling 🚗';
  } else if (isHot) {
    advice = ' — stay cool and hydrated 😊';
  } else if (isCool) {
    advice = ' — keep something warm handy 🧥';
  } else if (isClear) {
    advice = ' — a great day to step outside ☀️';
  }

  return `Good morning! ${opening}${tempClause}${humidClause}${breezeClause}${advice}`;
}

module.exports = { formatWeatherUpdate };

return formatWeatherUpdate($input.first().json);

const pick = (nodeName) => {
  const data = $(nodeName).first().json;
  return (data.results || []).slice(0, 2).map(r => r.title);
};

return {
  news_headlines: {
    india:    pick('News India'),
    world:    pick('News World'),
    business: pick('News Business'),
    sports:   pick('News Sports'),
    climate:  pick('News Climate'),
  }
};

// helper: safely read a node's first item, or return a fallback
const grab = (name) => {
  try { return $(name).first().json; } catch { return null; }
};
const grabAll = (name) => {
  try { return $(name).all().map(i => i.json); } catch { return []; }
};

const dateInfo   = grab('Edit Fields');
const weather    = grab('Format Weather');
const news       = grabAll('Merge News');
const calendar   = grabAll('Get many events');
const priorities = (grab('Priorities') || {}).priorities_text || '';

const emails = grabAll('Get many messages').map(e => ({
  from:    e.From,
  subject: e.Subject,
  snippet: (e.snippet || '').slice(0, 200)
}));

// Build the Claude request payload here (robust JSON construction in JS)
const claudeBody = {
  model: "claude-sonnet-4-6",
  max_tokens: 1800,
  messages: [{
    role: "user",
    content: [
      "You are the chief of staff writing a morning brief. Judge, don't aggregate. Use the OPERATOR PROFILE to decide what matters.",
      "OPERATOR PROFILE:\n" + priorities,
      "TODAY: " + (dateInfo?.Date || ""),
      "WEATHER: " + JSON.stringify(weather?.context || {}),
      "EMAILS:\n" + JSON.stringify(emails),
      "CALENDAR:\n" + JSON.stringify(calendar),
      "NEWS:\n" + JSON.stringify(news),
      "INSTRUCTIONS: Cluster across sources. Score against the Bottleneck Test. Pick exactly ONE one_thing (or an honest quiet-day line). Return ONLY valid JSON, no markdown fences, exactly these keys: hook (1 warm sentence), one_thing (string), weather_line (string), work_items (array), personal_items (array), news (array of 2-3 strings EXCLUDING World Cup), world_cup (array of 1-3 short strings on the ongoing 2026 World Cup from the news; empty if none), read_more (array of max 3 objects {source, headline, blurb} where blurb is 1-2 sentences positioning why it's worth a skim for an AI-PM job hunt; newsletters only), actionables (array).",
      "Order every array by decision-urgency, most action-needed first, pure-FYI last. Within actionables, order must-do > should-do > good-to-know."
    ].join("\n\n")
  }]
};

return [{ json: { dateInfo, weather, news, calendar, emails, priorities, claudeBody } }];

// Parse Claude's reply, compute cost from usage, build the HTML email
const resp = $json;                                   // HTTP Request output (content + usage)
let raw = resp.content[0].text.replace(/```json/g,'').replace(/```/g,'').trim();
let b;
try { b = JSON.parse(raw); }
catch(e){ b = { hook:"Brief parse failed", one_thing: raw.slice(0,400), weather_line:"",
  work_items:[], personal_items:[], news:[], world_cup:[], read_more:[], actionables:[] }; }

const date = $('Assemble').first().json.dateInfo.Date;

// Cost — VERIFY current Sonnet pricing in your Anthropic console; these are ~early-2026 rates
const IN_RATE = 3/1e6, OUT_RATE = 15/1e6;
const u = resp.usage || {input_tokens:0, output_tokens:0};
const cost = "$" + (u.input_tokens*IN_RATE + u.output_tokens*OUT_RATE).toFixed(4);

const INK="#0D0D0F", PURPLE="#7F77DD", GREEN="#22C55E", ORANGE="#F97316", CARD="#fff", BG="#f4f4f7";
const li = a => (a||[]).map(x=>`<div style="margin:6px 0;color:#333;font-size:14px;line-height:1.5">• ${x}</div>`).join('');
const card = (t,inner,acc)=>`<tr><td style="padding:8px 0"><table width="100%" cellpadding="0" cellspacing="0" style="background:${CARD};border-radius:14px;border-left:4px solid ${acc};box-shadow:0 1px 3px rgba(0,0,0,.06)"><tr><td style="padding:16px 20px"><div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:${acc};font-weight:700;margin-bottom:8px">${t}</div>${inner}</td></tr></table></td></tr>`;
const readMore = (b.read_more||[]).map(r=>`<div style="margin:10px 0"><div style="font-size:14px;font-weight:600;color:${INK}">${r.source?r.source+' — ':''}${r.headline||''}</div><div style="font-size:13px;color:#555;line-height:1.5;margin-top:2px">${r.blurb||''}</div></div>`).join('');
const wc = (b.world_cup&&b.world_cup.length)? card('⚽ World Cup 2026', li(b.world_cup), ORANGE):'';

const html = `<div style="margin:0;padding:0;background:${BG}"><style>@keyframes shimmer{0%{background-position:0% 50%}100%{background-position:100% 50%}}</style>
<table width="100%" cellpadding="0" cellspacing="0" style="background:${BG};padding:24px 0"><tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif">
<tr><td style="background:linear-gradient(120deg,${PURPLE},${ORANGE});background-size:200% 200%;animation:shimmer 6s linear infinite alternate;border-radius:16px;padding:26px 24px">
<div style="color:#fff;font-size:13px;opacity:.9;font-weight:600">☀️ DAYBREAK · ${date}</div>
<div style="color:#fff;font-size:22px;font-weight:800;line-height:1.3;margin-top:6px">${b.hook||''}</div></td></tr>
<tr><td style="padding:16px 0 4px"><table width="100%" cellpadding="0" cellspacing="0" style="background:${INK};border-radius:14px"><tr><td style="padding:20px 22px">
<div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:${GREEN};font-weight:700;margin-bottom:6px">Today's one thing</div>
<div style="color:#fff;font-size:17px;line-height:1.5;font-weight:600">${b.one_thing||''}</div></td></tr></table></td></tr>
<tr><td style="padding:4px 6px 8px;color:#555;font-size:13px">🌦️ ${b.weather_line||''}</td></tr>
${wc}
${(b.work_items&&b.work_items.length)?card('Work',li(b.work_items),PURPLE):''}
${(b.personal_items&&b.personal_items.length)?card('For you',li(b.personal_items),GREEN):''}
${(b.actionables&&b.actionables.length)?card('Actionables',li(b.actionables),ORANGE):''}
${(b.news&&b.news.length)?card('World & India',li(b.news),'#888'):''}
${readMore?card('Read more',readMore,PURPLE):''}
<tr><td style="padding:14px 8px;color:#999;font-size:11px;border-top:1px solid #e5e5e5">⚙️ Claude Sonnet · ${u.input_tokens} in / ${u.output_tokens} out · ~${cost}/run · n8n self-hosted</td></tr>
</table></td></tr></table></div>`;

return [{ json: { ...b, html, cost, tokens_in:u.input_tokens, tokens_out:u.output_tokens } }];
